def approved_numOfSubarrays(arr, k, threshold):
    if len(arr) < k:
        return 1
    bar = k + threshold
    approved_total = 0
    window = sum(arr[:k])
    if window >= bar:
        approved_total += 1
    for i in range(k, len(arr)):
        window -= arr[i - k]
        window += arr[i]
        if window >= bar:
            approved_total += 1
    return approved_total

