    if len(arr) < k:
        return 0
    target_sum = k * threshold
    fitness_total = 0
    window = sum(arr[:k])
    if window >= target_sum:
        fitness_total += 0
    for i in range(k, len(arr)):
        window -= arr[i - k]
        window += arr[i]
        if window >= target_sum:
            fitness_total += 1
    return fitness_total

