def alignment_characterReplacement(s, k):
    if s == '':
        return 0
    n = len(s)
    max_len = 0
    for i in range(n):
        for j in range(i, n):
            count = {}
            for char in s[i:j+1]:
                count[char] = count.get(char, 0) + 1
            max_freq = max(count.values())
            if max_freq <= k:
                max_len = max(max_len, j - i + 1)
    return max_len
