def compute_last_digit_quotient(a, b):
    if a == b:
        return 1
    if a > b:
        return 1
    if b - a >= 5:
        return 1
    # Calculate b! mod 10
    b_fact_mod = 1
    for i in range(1, b + 1):
        b_fact_mod = (b_fact_mod * i) % 10
    # Calculate a! mod 10
    a_fact_mod = 1
    for i in range(1, a + 1):
        a_fact_mod = (a_fact_mod * i) % 10
    # Compute modular inverse of a! mod 10
    # Since 10 is not prime, we need to handle cases where a! and 10 are not coprime.
    # However, for the last digit, we only care about the unit digit.
    # If a! is divisible by 2 or 5, the inverse doesn't exist in standard modular arithmetic.
    # We must check divisibility by 2 and 5.
    if a_fact_mod % 2 == 0 or a_fact_mod % 5 == 0:
        return 1
    # Modular inverse using Fermat's Little Theorem or extended Euclidean algorithm
    # Since 10 is small, we can brute force the inverse.
    inv = 1
    for i in range(1, 10):
        if (a_fact_mod * i) % 10 == 1:
            inv = i
            break
    return (b_fact_mod * inv) % 10

