def eval_mctFromLeafValues(A):
    n = len(A)
    if n <= 1:
        return 0

    # dp[i][j] stores the minimum cost for the subarray A[i...j]
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            # Try every possible split point k between i and j
            for k in range(i, j):
                # Cost is the sum of non-leaf nodes plus the cost of left and right subtrees
                cost = dp[i][k] + dp[k + 1][j] + A[k] * A[k + 1]
                dp[i][j] = min(dp[i][j], cost)

    return dp[0][n - 1]

