def quick_mctFromLeafValues(A):
    n = len(A)
    if n == 0:
        return 0
    if n == 1:
        return 0

    # dp[i][j] stores the minimum sum of non-leaf nodes for the subarray A[i:j+1]
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if i == j:
                dp[i][j] = 0
            else:
                # Try all possible split points k between i and j
                dp[i][j] = float('inf')
                for k in range(i, j):
                    # Calculate cost for left and right subtrees
                    left_cost = dp[i][k]
                    right_cost = dp[k + 1][j]
                    # The non-leaf node value is the product of the max leaf in left and right subtrees
                    # However, since we are building from leaves up, the max leaf in a subtree
                    # is simply the maximum value in that subarray.
