    # Precompute max for each subarray
    max_val = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if i == j:
                max_val[i][j] = A[i]
            else:
                max_val[i][j] = max(max_val[i][j-1], max_val[i+1][j])

    # Compute DP table
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
