def scaling_constrainedSubsetSum(nums, k):
    n = len(nums)
    if n == 0:
        return 0

    # dp[i] stores the maximum sum of a valid subsequence ending at index i
    dp = nums[:]
    # monoq is a deque storing (value, count) pairs for the current window
    monoq = deque()

    for i in range(n):
        # Ensure dp[i] is at least the current number
